package com.rootopathy.careos.administration.application;
import com.rootopathy.careos.administration.domain.ServiceCatalogue;import com.rootopathy.careos.governance.application.GovernedMutationExecutor;import com.rootopathy.careos.governance.domain.*;import com.rootopathy.careos.tenancy.application.TenantAuthorizationOperations;import com.rootopathy.careos.tenancy.domain.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;import java.util.regex.Pattern;import org.springframework.stereotype.Service;import tools.jackson.databind.ObjectMapper;
@Service public class ServiceCatalogueService{public static final String READ="service.catalog.read",MANAGE="service.catalog.manage",LIFECYCLE="service.catalog.lifecycle";private static final Pattern CODE=Pattern.compile("[A-Z0-9][A-Z0-9_-]{1,31}"),KEY=Pattern.compile("[A-Za-z0-9._:-]{16,128}"),ETAG=Pattern.compile("\"service-definition:([0-9a-fA-F-]{36}):([0-9]{1,19})\"");private final TenantAuthorizationOperations auth;private final GovernedMutationExecutor mutations;private final ServiceCatalogueStore store;private final ObjectMapper mapper;private final Clock clock;public ServiceCatalogueService(TenantAuthorizationOperations a,GovernedMutationExecutor m,ServiceCatalogueStore s,ObjectMapper o,Clock c){auth=a;mutations=m;store=s;mapper=o;clock=c;}public ServiceCatalogue directory(Read c){return auth.execute(req(c.organizationId,c.actorId,c.correlationId,READ,null,null,null),store::directory);}public IdempotencyOutcome create(Write c){return write(c,null);}public IdempotencyOutcome update(Write c){return write(c,revision(c.ifMatch,c.serviceId));}private IdempotencyOutcome write(Write c,Long revision){var reason=text(c.reason,"reason",10,500);key(c.idempotencyKey);var code=text(c.serviceCode,"serviceCode",2,32).toUpperCase(Locale.ROOT);if(!CODE.matcher(code).matches())throw new IllegalArgumentException("invalid serviceCode");var codingSystem=optional(c.codingSystem,120);var codingCode=optional(c.codingCode,120);if((codingSystem==null)!=(codingCode==null))throw new IllegalArgumentException("coding system and code must be supplied together");var draft=new ServiceCatalogueStore.Draft(code,text(c.displayName,"displayName",2,120),optional(c.clinicalName,160),optional(c.description,1000),codingSystem,codingCode,c.ownerResponsibilityId);var command=new IdempotencyCommand(MANAGE,c.idempotencyKey,hash(c.serviceId,revision,draft,reason),clock.instant().plusSeconds(86400));return mutations.execute(req(c.organizationId,c.actorId,c.correlationId,MANAGE,reason,null,null),command,x->{var r=revision==null?store.create(x,draft):store.update(x,c.serviceId,revision,draft);return mutation(r,revision==null?"created":"updated",reason,revision==null?201:200);});}public IdempotencyOutcome activate(Lifecycle c){return transition(c,"draft","active","activated",null);}public IdempotencyOutcome retire(Lifecycle c){return transition(c,"active","retired","retired",text(c.reason,"reason",10,500));}private IdempotencyOutcome transition(Lifecycle c,String from,String to,String change,String retirement){var reason=text(c.reason,"reason",10,500);key(c.idempotencyKey);var rev=revision(c.ifMatch,c.serviceId);var command=new IdempotencyCommand(LIFECYCLE,c.idempotencyKey,hash(c.serviceId,rev,to,reason),clock.instant().plusSeconds(86400));return mutations.execute(req(c.organizationId,c.actorId,c.correlationId,LIFECYCLE,reason,c.recentAuthenticationAt,c.mfaAuthenticatedAt),command,x->mutation(store.transition(x,c.serviceId,rev,from,to,retirement),change,reason,200));}private GovernedMutation mutation(ServiceCatalogueStore.Result r,String change,String reason,int status){var event="service.definition."+change;var payload=json(Map.of("serviceId",r.serviceId(),"fromState",r.fromState(),"toState",r.toState(),"lockVersion",r.lockVersion()));return new GovernedMutation(new IdempotentResponse(status,"application/json",json(r.directory())),new GovernanceEvidence(new AuditRecord(event,1,"service_definition",r.serviceId(),reason,payload),new OutboxRecord(event,1,"service_definition",r.serviceId(),payload)));}private TenantAuthorizationRequest req(UUID o,UUID a,String corr,String op,String reason,Instant recent,Instant mfa){return new TenantAuthorizationRequest(o,new AuthenticatedActorContext(a,"service-catalogue-administration",corr),new OperationKey(op),reason,recent,mfa,null);}private static String text(String v,String f,int min,int max){var n=v==null?"":v.strip();if(n.length()<min||n.length()>max||n.codePoints().anyMatch(Character::isISOControl))throw new IllegalArgumentException("invalid "+f);return n;}private static String optional(String v,int max){if(v==null||v.isBlank())return null;return text(v,"optional field",1,max);}private static void key(String k){if(k==null||!KEY.matcher(k).matches())throw new IllegalArgumentException("invalid Idempotency-Key");}private static long revision(String e,UUID id){var m=e==null?null:ETAG.matcher(e);if(m==null||!m.matches()||id==null||!UUID.fromString(m.group(1)).equals(id))throw new IllegalArgumentException("strong service If-Match required");return Long.parseLong(m.group(2));}private String json(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}}private static String hash(Object...v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Arrays.toString(v).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public record Read(UUID organizationId,UUID actorId,String correlationId){}public record Write(UUID organizationId,UUID actorId,String correlationId,String idempotencyKey,String ifMatch,UUID serviceId,String serviceCode,String displayName,String clinicalName,String description,String codingSystem,String codingCode,UUID ownerResponsibilityId,String reason){}public record Lifecycle(UUID organizationId,UUID actorId,String correlationId,String idempotencyKey,String ifMatch,UUID serviceId,String reason,Instant recentAuthenticationAt,Instant mfaAuthenticatedAt){}
}
